settings.markdownCss:
hr{
    height: 2px;
    border-width: 0;
    color: rgba(0,0,0,0.05);
    background-color: rgba(0,0,0,0.05);
}
p {
    margin: 0;
    font-family: 'Roboto';
    font-size: 14px;
    font-weight: 400;
    line-height: 20px;
}
.card {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.card-row {
    display: flex;
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
}

.card-title {
    color: rgba(0,0,0,0.38);
}
.card-value {
    color: rgba(0,0,0,0.76);
}
.card-value.status {
    padding: 1px 8px;
    border-radius: 8px;
}
.card-value.Running{
    background-color: rgba(25, 128, 56, 0.06);
    color: rgba(25, 128, 56, 1);
}
.card-value.Stopped{
    background-color: rgba(105, 105, 105, 0.06);
    color: rgba(105, 105, 105, 1);
}

